import os
from datetime import datetime, timedelta
from azure.monitor.query import MetricsQueryClient
from azure.identity import DefaultAzureCredential

def get_metric_statistics(resource_uri: str, metric_name: str, start_time: datetime, end_time: datetime, aggregation: str = "Average") -> dict:
    credential = DefaultAzureCredential()
    client = MetricsQueryClient(credential)

    metric_namespace = None
    if "/Microsoft.Compute/virtualMachines/" in resource_uri:
        metric_namespace = "Microsoft.Compute/virtualMachines"
    elif "/Microsoft.Web/sites/" in resource_uri:
        metric_namespace = "Microsoft.Web/sites"

    response = client.query_resource(
        resource_uri=resource_uri,
        metric_names=[metric_name],
        timespan=(start_time, end_time),
        interval=timedelta(hours=1),
        aggregations=[aggregation],
        metric_namespace=metric_namespace
    )

    result = {}
    for metric in response.metrics:
        for time_series in metric.timeseries:
            for data in time_series.data:
                if data.timestamp not in result:
                    result[data.timestamp] = {}
                if hasattr(data, aggregation.lower()):
                    result[data.timestamp][aggregation] = getattr(data, aggregation.lower())

    return result
